using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Diagnostics;using System.Drawing;using System.Drawing.Imaging;using System.Runtime.InteropServices;using System.Threading;using System.Threading.Tasks;

namespace AgitCon {
    // Only settings navigation. No file selection, Open, Send, Enter or chat text.
    internal static class ConfirmationNavigator {
        delegate bool EnumWindow(IntPtr w,IntPtr data);
        [StructLayout(LayoutKind.Sequential)]struct Mouse {public int X,Y;public uint Data,Flags,Time;public UIntPtr Extra;}
        [StructLayout(LayoutKind.Explicit,Size=32)]struct InputData{[FieldOffset(0)]public Mouse Mouse;}
        [StructLayout(LayoutKind.Sequential)]struct Input{public uint Type;public InputData Data;}
        [DllImport("user32.dll")]static extern bool EnumWindows(EnumWindow cb,IntPtr data);
        [DllImport("user32.dll")]static extern bool EnumChildWindows(IntPtr parent,EnumWindow cb,IntPtr data);
        [DllImport("user32.dll")]static extern IntPtr GetWindow(IntPtr w,uint command);
        [DllImport("user32.dll")]static extern int GetDlgCtrlID(IntPtr w);
        [DllImport("user32.dll")]static extern bool IsWindowVisible(IntPtr w);
        [DllImport("user32.dll")]static extern bool IsWindowEnabled(IntPtr w);
        [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern int GetClassName(IntPtr w,StringBuilder cls,int size);
        [DllImport("user32.dll")]static extern uint GetDpiForWindow(IntPtr w);
        [DllImport("user32.dll")]static extern bool SetForegroundWindow(IntPtr w);
        [DllImport("user32.dll")]static extern bool ShowWindowAsync(IntPtr w,int command);
        [DllImport("user32.dll")]static extern IntPtr WindowFromPhysicalPoint(Point point);
        [DllImport("user32.dll")]static extern bool SetPhysicalCursorPos(int x,int y);
        [DllImport("user32.dll")]static extern uint SendInput(uint count,Input[] input,int size);
        [DllImport("user32.dll")]static extern bool PrintWindow(IntPtr w,IntPtr dc,uint flags);
        [DllImport("gdi32.dll")]static extern bool SetViewportOrgEx(IntPtr dc,int x,int y,IntPtr old);
        [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern IntPtr SendMessageTimeout(IntPtr w,uint message,IntPtr wp,IntPtr lp,uint flags,uint timeout,out UIntPtr result);
        [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern bool PostMessage(IntPtr w,uint message,IntPtr wp,IntPtr lp);
        [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern IntPtr FindWindowEx(IntPtr parent,IntPtr after,string cls,string name);
        [DllImport("user32.dll")]static extern int GetMenuItemCount(IntPtr menu);
        [DllImport("user32.dll")]static extern uint GetMenuItemID(IntPtr menu,int position);
        [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern int GetMenuString(IntPtr menu,uint index,StringBuilder text,int size,uint flags);
        internal static uint Dpi(IntPtr window){return GetDpiForWindow(window);}
        internal static string Class(IntPtr w){var cls=new StringBuilder(128);GetClassName(w,cls,cls.Capacity);return cls.ToString();}
        static uint ProcessId(IntPtr w){uint id;Native.GetWindowThreadProcessId(w,out id);return id;}
        internal static bool SameProcess(IntPtr w,uint process){uint id;Native.GetWindowThreadProcessId(w,out id);return w!=IntPtr.Zero&&id==process;}
        internal static bool OwnedBy(IntPtr w,IntPtr root){for(int i=0;i<8&&w!=IntPtr.Zero;i++,w=GetWindow(w,4))if(w==root)return true;return false;}
        internal static IntPtr FindMain(uint process){var result=new List<IntPtr>();EnumWindow cb=(w,d)=>{if(SameProcess(w,process)&&Native.Title(w)=="카카오톡"&&Class(w)=="EVA_Window_Dblclk")result.Add(w);return true;};EnumWindows(cb,IntPtr.Zero);return result.Count==1?result[0]:IntPtr.Zero;}
        static IntPtr Pane(IntPtr settings,int id){var result=new List<IntPtr>();EnumWindow cb=(w,d)=>{if(GetDlgCtrlID(w)==id&&IsWindowVisible(w))result.Add(w);return true;};EnumChildWindows(settings,cb,IntPtr.Zero);return result.Count==1?result[0]:IntPtr.Zero;}
        static IntPtr Settings(uint process,IntPtr main){var result=new List<IntPtr>();EnumWindow cb=(w,d)=>{if(w!=main&&SameProcess(w,process)&&IsWindowVisible(w)&&Class(w)=="EVA_Window_Dblclk"&&OwnedBy(w,main)&&(Pane(w,1073)!=IntPtr.Zero||Pane(w,1137)!=IntPtr.Zero))result.Add(w);return true;};EnumWindows(cb,IntPtr.Zero);return result.Count==1?result[0]:IntPtr.Zero;}
        internal static bool ExpectedForeground(IntPtr w,uint process,IntPtr main,IntPtr source,IntPtr target){if(w==IntPtr.Zero)return false;if(w==source||w==target||w==main)return true;if(!SameProcess(w,process))return false;return Class(w)=="#32768"||((Class(w)=="EVA_Window_Dblclk"||Class(w)=="EVA_Menu")&&OwnedBy(w,main));}
        internal static Bitmap Capture(IntPtr window,Rectangle crop){using(new DpiGeometry.Scope(window))return CaptureInContext(window,crop);}
        static Bitmap CaptureInContext(IntPtr window,Rectangle crop){if(!IsWindowVisible(window)||crop.Width<1||crop.Height<1||crop.Width>4096||crop.Height>4096)throw new InvalidOperationException("Capture bounds");var image=new Bitmap(crop.Width,crop.Height,PixelFormat.Format32bppArgb);try{using(var graphics=Graphics.FromImage(image)){graphics.Clear(Color.White);IntPtr dc=graphics.GetHdc();try{SetViewportOrgEx(dc,-crop.X,-crop.Y,IntPtr.Zero);if(!PrintWindow(window,dc,0))throw new InvalidOperationException("Capture failed");}finally{graphics.ReleaseHdc(dc);}}return image;}catch{image.Dispose();throw;}}
        static bool Click(IntPtr w,Point point,Func<bool> safe,CancellationToken token,IntPtr foregroundOwner=default(IntPtr),Size? capturedSize=null){token.ThrowIfCancellationRequested();IntPtr foreground=Native.GetForegroundWindow();if(!safe()||(foreground!=w&&(foreground!=foregroundOwner||!OwnedBy(w,foregroundOwner)))||!IsWindowVisible(w)||!IsWindowEnabled(w))return false;Native.Rect raster,physical;if(!DpiGeometry.GetRect(w,out raster)||!DpiGeometry.GetPhysicalRect(w,out physical))return false;var size=new Size(raster.Right-raster.Left,raster.Bottom-raster.Top);if(capturedSize.HasValue&&capturedSize.Value!=size)return false;Point screen;if(!DpiGeometry.MapPoint(size,Rectangle.FromLTRB(physical.Left,physical.Top,physical.Right,physical.Bottom),point,out screen))return false;if(!SetPhysicalCursorPos(screen.X,screen.Y)||!safe())return false;IntPtr after=Native.GetForegroundWindow();if(after!=w&&(after!=foregroundOwner||!OwnedBy(w,foregroundOwner)))return false;IntPtr hit=WindowFromPhysicalPoint(screen),root=Native.GetAncestor(hit,2);if(!SameProcess(hit,ProcessId(w))||(root!=w&&!(Class(root)=="EVA_Menu"&&OwnedBy(root,w))))return false;var input=new[]{new Input{Data=new InputData{Mouse=new Mouse{Flags=2}}},new Input{Data=new InputData{Mouse=new Mouse{Flags=4}}}};return SendInput(2,input,Marshal.SizeOf(typeof(Input)))==2;}
        static string menuStage;
        internal sealed class GearReading {internal Point? Point;internal Size Size;internal string Detail;}
        // Do not click a gear from a single partially rendered frame.
        internal static async Task<GearReading> StableGear(Func<Bitmap> capture,float scale,Func<bool> safe,CancellationToken token,int pause=100){
            Point? previous=null;Size previousSize=Size.Empty;var result=new GearReading();
            for(int attempt=0;attempt<4;attempt++){
                token.ThrowIfCancellationRequested();if(!safe()){result.Detail="focus-changed";return result;}
                using(var image=capture()){
                    int min=255,max=0;for(int y=0;y<image.Height;y+=Math.Max(1,image.Height/32))for(int x=0;x<image.Width;x+=Math.Max(1,image.Width/32)){int value=image.GetPixel(x,y).R;min=Math.Min(min,value);max=Math.Max(max,value);}
                    var found=ConfirmationVision.Gear(image,scale);result.Detail="frame="+(attempt+1)+"/crop="+image.Width+"x"+image.Height+"/range="+min+"-"+max+"/match="+found.HasValue;
                    if(found.HasValue&&previous.HasValue&&previousSize==image.Size&&Math.Abs(previous.Value.X-found.Value.X)<=2&&Math.Abs(previous.Value.Y-found.Value.Y)<=2){result.Point=found;result.Size=image.Size;return result;}
                    previous=found;previousSize=image.Size;
                }
                if(attempt<3)await Task.Delay(pause,token);
            }
            return result;
        }
        static bool OpenSettingsMenu(uint process,IntPtr main,Func<bool> safe,CancellationToken token){menuStage="menu-search";var menus=new List<IntPtr>();EnumWindow cb=(w,d)=>{if(SameProcess(w,process)&&Class(w)=="#32768"&&IsWindowVisible(w))menus.Add(w);return true;};EnumWindows(cb,IntPtr.Zero);for(IntPtr popup=FindWindowEx(IntPtr.Zero,IntPtr.Zero,"#32768",null);popup!=IntPtr.Zero;popup=FindWindowEx(IntPtr.Zero,popup,"#32768",null))if(SameProcess(popup,process)&&IsWindowVisible(popup)&&!menus.Contains(popup))menus.Add(popup);menuStage="menus-"+menus.Count;if(menus.Count!=1||!safe())return false;UIntPtr result;if(SendMessageTimeout(menus[0],0x01e1,IntPtr.Zero,IntPtr.Zero,0x22,200,out result)==IntPtr.Zero)return false;IntPtr menu=new IntPtr(unchecked((long)result.ToUInt64()));int count=GetMenuItemCount(menu);menuStage="items-"+count;if(count<2||count>12)return false;var matches=new List<uint>();bool logout=false,exit=false;for(uint i=0;i<count;i++){var text=new StringBuilder(160);GetMenuString(menu,i,text,text.Capacity,0x400);string name=text.ToString().Split('\t')[0].Replace("&","").Trim();if(name=="설정")matches.Add(GetMenuItemID(menu,(int)i));if(name=="로그아웃")logout=true;if(name=="종료")exit=true;}menuStage="matches-"+matches.Count+"-logout-"+logout+"-exit-"+exit;token.ThrowIfCancellationRequested();if(matches.Count!=1||matches[0]==UInt32.MaxValue||!logout||!exit||!safe()||!ExpectedForeground(Native.GetForegroundWindow(),process,main,main,main))return false;return PostMessage(main,0x0111,new IntPtr(matches[0]),IntPtr.Zero);}
        static async Task<bool> CustomSettingsMenu(uint process,IntPtr main,Func<bool> safe,CancellationToken token){var menus=new List<IntPtr>();EnumWindow cb=(w,d)=>{if(SameProcess(w,process)&&IsWindowVisible(w)&&Class(w)=="EVA_Menu"&&OwnedBy(w,main))menus.Add(w);return true;};EnumWindows(cb,IntPtr.Zero);menuStage="custom-menus-"+menus.Count;if(menus.Count!=1||!safe())return false;Native.Rect rect;if(!DpiGeometry.GetRect(menus[0],out rect)||rect.Right-rect.Left<60||rect.Right-rect.Left>1800||rect.Bottom-rect.Top<60||rect.Bottom-rect.Top>1600)return false;RectangleF? settings=null;float scale=Math.Max(1,Dpi(menus[0])/96f);int pad=(int)(16*scale);using(var bitmap=Capture(menus[0],new Rectangle(0,0,rect.Right-rect.Left,rect.Bottom-rect.Top)))using(var padded=new Bitmap(bitmap.Width+pad*2,bitmap.Height+pad*2,PixelFormat.Format32bppArgb)){using(var g=Graphics.FromImage(padded)){g.Clear(bitmap.GetPixel(0,0));g.DrawImage(bitmap,new Rectangle(pad,pad,bitmap.Width,bitmap.Height),0,0,bitmap.Width,bitmap.Height,GraphicsUnit.Pixel);}foreach(int width in new[]{320,480,640}){float factor=(float)width/padded.Width;using(var large=ConfirmationVision.Resize(padded,width,(int)Math.Round(padded.Height*factor))){var text=await ConfirmationVision.Ocr(large,token);var found=ConfirmationVision.LabelBounds(text,"설정");if(found.HasValue&&ConfirmationVision.LabelBounds(text,"로그아웃").HasValue&&ConfirmationVision.LabelBounds(text,"종료").HasValue){var r=found.Value;settings=new RectangleF(r.X/factor-pad,r.Y/factor-pad,r.Width/factor,r.Height/factor);break;}}}if(!settings.HasValue){menuStage="custom-labels";return false;}}
            var point=new Point((int)(settings.Value.Left+settings.Value.Width*.5),(int)(settings.Value.Top+settings.Value.Height*.5));return Click(menus[0],point,safe,token,main,new Size(rect.Right-rect.Left,rect.Bottom-rect.Top));}

        internal static async Task<ConfirmationReading> ReadVisible(uint process,IntPtr main,CancellationToken token){IntPtr settings=Settings(process,main),pane=settings==IntPtr.Zero?IntPtr.Zero:Pane(settings,1073);if(pane==IntPtr.Zero)return ConfirmationReading.Unknown("settings-pane-unavailable");Native.Rect r;if(!DpiGeometry.GetRect(pane,out r))return ConfirmationReading.Unknown("pane-bounds");int width=r.Right-r.Left,height=r.Bottom-r.Top;if(width<250||height<200||width>4096||height>4096)return ConfirmationReading.Unknown("pane-size");int[] states=new int[2];for(int i=0;i<2;i++){token.ThrowIfCancellationRequested();if(Settings(process,main)!=settings||Pane(settings,1073)!=pane)return ConfirmationReading.Unknown("pane-changed");using(var image=Capture(pane,new Rectangle(0,0,width,height)))states[i]=await ConfirmationVision.Read(image,token);if(i==0)await Task.Delay(90,token);}if(states[0]==0||states[0]!=states[1])return ConfirmationReading.Unknown("visual-uncertain");return new ConfirmationReading{State=states[0],Stage=states[0]==1?"visual-on":"visual-off"};}
        internal static async Task<ConfirmationReading> Verify(uint process,IntPtr main,IntPtr source,Func<bool> safe,CancellationToken token){
            IntPtr settings=IntPtr.Zero;bool created=false;try{token.ThrowIfCancellationRequested();if((await OcrSupport.CheckAsync()).State!=OcrState.Available)return ConfirmationReading.Unknown("korean-ocr-unavailable");if(main==IntPtr.Zero||!SameProcess(main,process)||!safe()||Native.GetForegroundWindow()!=source)return ConfirmationReading.Unknown("navigation-source");settings=Settings(process,main);
                if(settings==IntPtr.Zero){bool restored=Native.IsIconic(main);if(restored){if(!safe())return ConfirmationReading.Unknown("main-restore-source");ShowWindowAsync(main,9);for(int i=0;i<25&&Native.IsIconic(main);i++){await Task.Delay(40,token);if(!safe())return ConfirmationReading.Unknown("main-restore-focus");}if(Native.IsIconic(main))return ConfirmationReading.Unknown("main-still-minimized");}if(!SetForegroundWindow(main))return ConfirmationReading.Unknown("main-activation");await Task.Delay(80,token);if(!safe()||Native.GetForegroundWindow()!=main)return ConfirmationReading.Unknown("main-focus");Native.Rect rect;if(!DpiGeometry.GetRect(main,out rect))return ConfirmationReading.Unknown("main-bounds");float scale=GetDpiForWindow(main)/96f;if(scale<.75||scale>4.25)return ConfirmationReading.Unknown("main-dpi");var rasterSize=new Size(rect.Right-rect.Left,rect.Bottom-rect.Top);var crop=DpiGeometry.SidebarCrop(rasterSize,scale);var observed=await StableGear(()=>Capture(main,crop),scale,()=>safe()&&Native.GetForegroundWindow()==main&&!Native.IsIconic(main),token);Point? gear=observed.Point;if(gear.HasValue)gear=new Point(gear.Value.X+crop.X,gear.Value.Y+crop.Y);if(!gear.HasValue)return ConfirmationReading.Unknown("gear-unrecognized/main="+rasterSize.Width+"x"+rasterSize.Height+"/dpi="+GetDpiForWindow(main)+"/restored="+restored+"/"+observed.Detail);menuStage="gear-"+gear.Value.X+","+gear.Value.Y;if(!Click(main,gear.Value,safe,token,capturedSize:rasterSize))return ConfirmationReading.Unknown("gear-focus");await Task.Delay(100,token);if(!OpenSettingsMenu(process,main,safe,token)&&!await CustomSettingsMenu(process,main,safe,token))return ConfirmationReading.Unknown("settings-menu-unrecognized/"+menuStage);for(int i=0;i<25;i++){await Task.Delay(40,token);if(!safe())return ConfirmationReading.Unknown("settings-focus-lost");settings=Settings(process,main);if(settings!=IntPtr.Zero){created=true;break;}}if(settings==IntPtr.Zero)return ConfirmationReading.Unknown("settings-not-opened");}
                if(!safe()||!SameProcess(settings,process)||!OwnedBy(settings,main))return ConfirmationReading.Unknown("settings-owner");if(!SetForegroundWindow(settings))return ConfirmationReading.Unknown("settings-activation");await Task.Delay(60,token);Native.Rect sr;if(!DpiGeometry.GetRect(settings,out sr))return ConfirmationReading.Unknown("settings-bounds");float settingsScale=GetDpiForWindow(settings)/96f;RectangleF? chat;using(var nav=Capture(settings,new Rectangle(0,0,(int)(100*settingsScale),sr.Bottom-sr.Top))){float factor=200f/nav.Width;using(var enlarged=ConfirmationVision.Resize(nav,200,(int)Math.Round(nav.Height*factor))){var text=await ConfirmationVision.Ocr(enlarged,token);chat=ConfirmationVision.LabelBounds(text,"채팅");if(chat.HasValue){var b=chat.Value;chat=new RectangleF(b.X/factor,b.Y/factor,b.Width/factor,b.Height/factor);}}}if(!chat.HasValue||chat.Value.Left<2||chat.Value.Right>100*settingsScale||chat.Value.Top<60*settingsScale)return ConfirmationReading.Unknown("chat-tab-unrecognized");var location=new Point((int)(chat.Value.Left+chat.Value.Width*.5),(int)(chat.Value.Top+chat.Value.Height*.5));if(!Click(settings,location,safe,token,capturedSize:new Size(sr.Right-sr.Left,sr.Bottom-sr.Top)))return ConfirmationReading.Unknown("chat-tab-focus");await Task.Delay(120,token);var reading=await ReadVisible(process,main,token);if(!safe())return ConfirmationReading.Unknown("reading-focus-lost");
                // WM_CLOSE is asynchronous: wait for the modal window to disappear before restoring source focus.
                if(created){PostMessage(settings,0x0010,IntPtr.Zero,IntPtr.Zero);for(int i=0;i<30&&Native.IsWindow(settings)&&IsWindowVisible(settings);i++)await Task.Delay(20,token);if(Native.IsWindow(settings)&&IsWindowVisible(settings))return ConfirmationReading.Unknown("settings-close-pending");created=false;}
                if(!safe()||!SetForegroundWindow(source))return ConfirmationReading.Unknown("source-restore");for(int i=0;i<15&&Native.GetForegroundWindow()!=source;i++)await Task.Delay(20,token);if(!safe()||Native.GetForegroundWindow()!=source)return ConfirmationReading.Unknown("source-restore-focus");return reading;
            }catch(OperationCanceledException){return ConfirmationReading.Unknown("canceled");}catch(Exception){return ConfirmationReading.Unknown("navigation-or-ocr-failed");}
            finally{if(safe()){if(created&&settings!=IntPtr.Zero&&SameProcess(settings,process)&&OwnedBy(settings,main)&&Native.GetForegroundWindow()==settings)PostMessage(settings,0x0010,IntPtr.Zero,IntPtr.Zero);if(Native.IsWindow(source))SetForegroundWindow(source);}}
        }
    }
